# ==============================================================================# 024_PERMISSION_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS permissions(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    role TEXT,    permission TEXT)""")conn.commit()PERMISSIONS = {    "ADMIN":[        "MISSION_CREATE",        "MISSION_DELETE",        "MISSION_UPDATE",        "MISSION_VIEW",        "SYSTEM_ADMIN",        "API_ACCESS",        "USER_CREATE",        "USER_DELETE"    ],    "MANAGER":[        "MISSION_CREATE",        "MISSION_UPDATE",        "MISSION_VIEW",        "API_ACCESS"    ],    "USER":[        "MISSION_VIEW"    ]}for role, lista in PERMISSIONS.items():    for permission in lista:        cur.execute("""        SELECT id        FROM permissions        WHERE role=?        AND permission=?        """,(role,permission))        if cur.fetchone() is None:            cur.execute("""            INSERT INTO permissions(                created_at,                role,                permission            )            VALUES(?,?,?)            """,(                datetime.now().isoformat(),                role,                permission            ))conn.commit()cur.execute("""SELECTrole,COUNT(*) totalFROM permissionsGROUP BY roleORDER BY role""")print("="*80)print("PERMISSION ENGINE")print("="*80)for row in cur.fetchall():    print(f"{row['role']:<10} {row['total']}")print("="*80)conn.close()

